  exitSummary: function(dateStr, code, reason) {
    var codeStr = code === -1 ? 'exit code unknown' : 'exit code ' + (code !== null && code !== undefined ? code : '—');
    return dateStr + ' · ' + codeStr + ' · ' + (reason || '');
  },
